//! Generated by Codex. Host handles opened by a procedure are scoped to its call.

use super::invocation_limits::InvocationContext;
use ::conn::worker_local::WorkerLocalRef;
use mudu::common::id::OID;
use mudu::common::result::RS;
use mudu::error::ErrorCode;
use mudu::mudu_error;
use mudu_binding::codec::syscall_payload::*;
use mudu_sys::sync::SMutex;

#[derive(Default)]
pub(crate) struct HostResources {
    sessions: Vec<(WorkerLocalRef, OID)>,
    files: Vec<(WorkerLocalRef, OID, u32)>,
}

impl InvocationContext {
    pub(crate) fn prepare_host(&self, kind: &str, input: &[u8]) -> wasmtime::Result<()> {
        self.enter_host(input.len())?;
        if matches!(kind, "open" | "fs_open") {
            let resources = self.resources.lock()?;
            if resources.sessions.len() + resources.files.len() >= self.limits.max_resources {
                return Err(wasmtime::Error::msg("procedure host handle limit reached"));
            }
        }
        let requested = match kind {
            "fs_read" => decode_fs_read_request(input).ok().map(|(_, size)| size),
            "fs_pread" => decode_fs_pread_request(input).ok().map(|(_, _, size)| size),
            _ => None,
        };
        if requested.is_some_and(|size| size as usize > self.limits.max_output_bytes) {
            return Err(wasmtime::Error::msg(
                "procedure file read exceeds output budget",
            ));
        }
        Ok(())
    }

    // Record successful opens before checking cancellation: a host operation
    // may finish after the deadline, and its handle still needs closing.
    pub(crate) fn record_host(
        &self,
        kind: &str,
        input: &[u8],
        output: &[u8],
        worker: Option<WorkerLocalRef>,
    ) -> wasmtime::Result<()> {
        let Some(worker) = worker else {
            return Ok(());
        };
        let mut resources = self.resources.lock()?;
        match kind {
            "open" => {
                if let Ok(session) = decode_open_result(output) {
                    resources.sessions.push((worker, session));
                }
            }
            "close" if decode_close_result(output).is_ok() => {
                if let Ok(session) = decode_close_request(input) {
                    resources.sessions.retain(|(_, id)| *id != session.to_oid());
                }
            }
            "fs_open" => {
                if let Ok(fd) = decode_fs_open_result(output) {
                    if let Some(session) = worker.current_session_id() {
                        resources.files.push((worker, session, fd));
                    } else {
                        return Err(wasmtime::Error::msg(
                            "opened file without bound worker session",
                        ));
                    }
                }
            }
            "fs_close" if decode_fs_close_result(output).is_ok() => {
                if let Ok(fd) = decode_fs_close_request(input) {
                    let session = worker.current_session_id();
                    resources
                        .files
                        .retain(|(_, id, open_fd)| Some(*id) != session || *open_fd != fd);
                }
            }
            _ => {}
        }
        Ok(())
    }

    pub(crate) async fn cleanup_resources(&self) -> RS<()> {
        let resources = std::mem::take(&mut *self.resources.lock()?);
        let mut error = None;
        for (worker, session, fd) in resources.files {
            let result = match worker.fs_service() {
                Ok(service) => service.fs_close(session, fd).await,
                Err(err) => Err(err),
            };
            if let Err(err) = result {
                error.get_or_insert(err);
            }
        }
        for (worker, session) in resources.sessions {
            if let Err(err) = worker.close_async(session).await {
                error.get_or_insert(err);
            }
        }
        match error {
            Some(error) => Err(mudu_error!(
                ErrorCode::Internal,
                "procedure host-resource cleanup failed",
                error
            )),
            None => Ok(()),
        }
    }
}

pub(crate) fn new_resources() -> SMutex<HostResources> {
    SMutex::new(HostResources::default())
}
